        ? MESSAGE_INPUT_PLACEHOLDER_QUEUED
        : (running ? MESSAGE_INPUT_PLACEHOLDER_RUNNING : MESSAGE_INPUT_PLACEHOLDER_DEFAULT);
    messageInput.placeholder = typeof translateUiString === 'function'
