                + '/history_snapshot?turns=' + encodeURIComponent(String(HISTORY_DIALOGUES_PER_PAGE))
                + '&event_budget=' + encodeURIComponent(String(HISTORY_EVENT_BUDGET))
                + '&include_aux=false&prefer_active_turn=true';
