        let pageMeta = null;
        if (Array.isArray(raw)) {
            events = raw;
        } else if (raw && typeof raw === 'object' && Array.isArray(raw.events)) {
            events = raw.events;
            const pageTotal = Number(raw.total) || 0;
            const pageRangeEnd = Number(raw.range_end) || 0;
