            delete agg.dataset.procDurationMs;
        } else {
            agg.dataset.procDurationMs = String(Math.max(0, Math.round(Number(event.duration_ms))));
        }
    }
    if (event.react_loops != null && Number.isFinite(Number(event.react_loops))) {
