    if (!state || !restoreHistoryPrependViewport(state)) return;
    var stream = state.stream, port = state.port;
    var observer = null, timer = 0, raf = 0, stopped = false;
    var inputs = ['wheel', 'touchstart', 'pointerdown', 'keydown'];
