/**
 * 尾部窗口起点（行边界）：保留最后 tailLines 行，且字符数不超过 tailChars
 * 单个逻辑行超预算时按字符裁剪；实际写入再对齐到实测的视觉行边界。
 */
function findLlmStreamTailStart(text, tailLines, tailChars) {
    var total = text.length;
